"""
scripts/seed_questions.py
=========================
Standalone DB seeder for the PlaceBuddy MCQ engine.

Run from the backend/ directory:
    python ../scripts/seed_questions.py

Inserts 70 pre-baked MCQ questions into mcq_questions covering 7 core skills
(python, react, fastapi, sql, docker, typescript, git).
Each skill: 3 Easy + 4 Medium + 3 Hard.
Re-running is safe -- idempotent duplicate check on (skill, difficulty, question_text[:80]).
"""
import logging, sys, os
from pathlib import Path

_BACKEND_DIR = Path(__file__).resolve().parent.parent / "backend"
if str(_BACKEND_DIR) not in sys.path:
    sys.path.insert(0, str(_BACKEND_DIR))

_ENV_PATH = _BACKEND_DIR / "app" / ".env"
if _ENV_PATH.exists():
    with open(_ENV_PATH, encoding="utf-8") as _fh:
        for _line in _fh:
            _line = _line.strip()
            if "=" in _line and not _line.startswith("#"):
                _k, _v = _line.split("=", 1)
                os.environ.setdefault(_k.strip(), _v.strip())

from app.db.database import SessionLocal, engine, Base
from app.db.models import Question

logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s  %(levelname)-8s  %(message)s",
    datefmt="%H:%M:%S",
)
logger = logging.getLogger("seed")

# ---------------------------------------------------------------------------
# Pre-baked question bank  (70 questions across 7 skills x 3 difficulties)
