# ---------------------------------------------------------------------------
# Seeder
# ---------------------------------------------------------------------------

def _ensure_table(db) -> None:
    Base.metadata.create_all(bind=engine)
    logger.info("Table check complete.")


def _already_exists(db, item: dict) -> bool:
    snippet = item["question_text"][:80]
    return (
        db.query(Question)
        .filter(
            Question.skill == item["skill"],
            Question.difficulty == item["difficulty"],
            Question.question_text.startswith(snippet),
        )
        .first()
    ) is not None


def seed(db) -> None:
    inserted = skipped = errors = 0
    for item in SEED_BANK:
        try:
            if _already_exists(db, item):
                skipped += 1
                continue
            q = Question(
                skill=item["skill"],
                forensic_tier=item["forensic_tier"],
                difficulty=item["difficulty"],
                seniority_tier=None,
                question_text=item["question_text"],
                options=item["options"],
                correct_answer=item["correct_answer"],
                explanation=item["explanation"],
            )
            db.add(q)
            inserted += 1
        except Exception as exc:
            errors += 1
            logger.error("Error: %s -- %s", item.get("question_text", "")[:50], exc)

    if inserted > 0:
        try:
            db.commit()
            logger.info("Committed %d new questions.", inserted)
        except Exception as exc:
            db.rollback()
            logger.error("Commit failed: %s", exc)
            raise

    logger.info(
        "Seed: %d total | %d inserted | %d skipped | %d errors",
        len(SEED_BANK), inserted, skipped, errors,
    )


def main() -> None:
    logger.info("Starting PlaceBuddy MCQ seed script...")
    db = SessionLocal()
    try:
        _ensure_table(db)
        seed(db)
    except Exception as exc:
        logger.error("Seed failed: %s", exc, exc_info=True)
        sys.exit(1)
    finally:
        db.close()
    logger.info("Done. Run `python run.py` -- MCQ cache is ready.")


if __name__ == "__main__":
    main()
